#Requires -Version 5.1
# fix-dashboard-semana-sinasignar.ps1
# El panel "Sin asignar" solo existia en la vista DIA del dashboard.
# En vista SEMANA no habia nada, por eso Luis y Tarsicio no aparecian
# (Luis esta asignado lun 13, Tarsicio jue 16 — pero el martes 14
# no tienen asignacion, asi que en vista dia del martes aparecian como sin asignar).
# Fix: añadir panel "Sin asignar esta semana" en la vista semana,
# usando la UNION de IDs asignados en cualquier dia de la semana.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix sin asignar vista semana" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\dashboard\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\dashboard\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("Sin asignar esta semana")) { Write-Host "  OK: panel sin asignar en vista semana" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("assignedThisWeek")) { Write-Host "  OK: union de IDs de toda la semana" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  git add src\app\dashboard\page.tsx"
Write-Host '  git commit -m "fix: sin asignar en vista semana - union de toda la semana"'
Write-Host "  git push"
